files.content:
:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --ink: #f4f4f4;
  --accent: #41a6f6;
  --accent-2: #73eff7;
  --muted: #a0a8c0;
  --shadow: #0d0f1a;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

html, body { height: 100%; }

body {
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(65,166,246,0.08) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(65,166,246,0.08) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(115,239,247,0.08) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(115,239,247,0.08) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--shadow);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px;
  border-radius: 0;
}

h1 {
  margin: 0 0 4px;
  font-size: 28px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent-2);
  text-shadow: 2px 2px 0 var(--shadow);
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 16px;
}

.field {
  margin-bottom: 20px;
  border: 0;
  padding: 0;
}

label, legend {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  font-size: 16px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 18px;
  font-family: inherit;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--shadow);
  border-radius: 0;
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--accent-2);
  box-shadow: 0 0 0 3px var(--accent);
}

.hint {
  display: block;
  margin-top: 6px;
  font-size: 14px;
  color: var(--muted);
}

.tip-buttons {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1 1 0;
  min-width: 72px;
  padding: 12px 8px;
  font-size: 18px;
  font-weight: 700;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--shadow);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--shadow);
  transition: transform 0.05s ease, background 0.15s ease;
}

.tip-btn:hover { background: var(--accent-2); }

.tip-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--accent-2), 3px 3px 0 var(--shadow);
}

.tip-btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--shadow); }

.tip-btn[aria-pressed="true"] {
  background: var(--accent-2);
  color: var(--bg);
  box-shadow: inset 2px 2px 0 var(--shadow);
}

.results {
  margin-top: 4px;
  border-top: 3px dashed var(--shadow);
  padding-top: 16px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 8px 0;
}

.result-label { color: var(--muted); font-size: 16px; }

.result-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--accent-2);
  font-variant-numeric: tabular-nums;
}

.result-row.total .result-value { font-size: 28px; color: var(--ink); }

@media (max-width: 400px) {
  .card { padding: 18px; box-shadow: 6px 6px 0 var(--shadow); }
  h1 { font-size: 24px; }
  .result-row.total .result-value { font-size: 24px; }
}

(function () {
  "use strict";

  var billInput = document.getElementById("bill");
  var peopleInput = document.getElementById("people");
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll(".tip-btn"));
  var tipOut = document.getElementById("tipPerPerson");
  var totalOut = document.getElementById("totalPerPerson");

  var tipPercent = 0;

  function money(n) {
    return "$" + n.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (!isFinite(bill) || bill < 0) bill = 0;
    if (!isFinite(people) || people < 1) people = 1;

    var tip = bill * (tipPercent / 100);
    var tipPerPerson = tip / people;
    var totalPerPerson = (bill + tip) / people;

    tipOut.textContent = money(tipPerPerson);
    totalOut.textContent = money(totalPerPerson);
  }

  function selectTip(button) {
    tipPercent = parseFloat(button.getAttribute("data-tip"));
    tipButtons.forEach(function (btn) {
      btn.setAttribute("aria-pressed", btn === button ? "true" : "false");
    });
    calculate();
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener("click", function () {
      selectTip(btn);
    });
  });

  billInput.addEventListener("input", calculate);
  peopleInput.addEventListener("input", calculate);

  // Default to 15% on load
  var defaultBtn = tipButtons.filter(function (b) {
    return b.getAttribute("data-tip") === "15";
  })[0];
  if (defaultBtn) selectTip(defaultBtn);
  else calculate();
})();
